PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyHolderId (COUNT(DISTINCT ?policy) AS ?policyCount)
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:hasPolicyHolder ?policyHolder .
    ?policyHolder in:policyHolderId ?policyHolderId .
  }
}
GROUP BY ?policyHolderId
ORDER BY ?policyHolderId

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?agentId ?policyNumber ?claimNumber ?lossPaymentAmount
WHERE {
  SERVICE <mapped> {
    ?policy in:soldByAgent ?agent ;
            in:policyNumber ?policyNumber .

    ?agent in:agentId ?agentId .

    ?coverage in:hasPolicy ?policy .

    ?claim in:against ?coverage ;
           in:claimNumber ?claimNumber ;
           in:hasLossPayment ?lossPayment .

    ?lossPayment in:lossPaymentAmount ?lossPaymentAmount .
  }
}
ORDER BY ?agentId ?policyNumber ?claimNumber ?lossPaymentAmount

PREFIX in: <http://data.world/schema/insurance/>

SELECT DISTINCT ?agent ?policy ?claim ?catastrophe
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:soldByAgent ?agent .

    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy .

    ?claim a in:Claim ;
           in:against ?coverage ;
           in:hasCatastrophe ?catastrophe .
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policy ?policyNumber ?policyHolder ?policyHolderId
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:hasPolicyHolder ?policyHolder .

    OPTIONAL { ?policy in:policyNumber ?policyNumber . }
    OPTIONAL { ?policyHolder in:policyHolderId ?policyHolderId . }
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT DISTINCT ?policyNumber ?claimNumber
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:against ?coverage .

    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy .

    ?policy a in:Policy ;
            in:policyNumber ?policyNumber .
  }
}
ORDER BY ?policyNumber ?claimNumber
